{
int ret;
struct data *buf;
char *message, *message2;
ret=tpstart((TPSTART_T *)NULL);
if (ret==-1) { error processing }
buf=(struct data *)tpalloc(“STRUCT”, “data”,0);
if (buf==NULL) { error processing }

