{
int ret;
char *SDLFI;
SDLFI=tpgetenv(“SDLFILE”);
if (SDLFI=NULL) ret=tpputenv(“SDLFILE=/tmax/sample/sdl/test.sdl”);
if (ret<0) { error processing }

