●プロトタイプ
#include <usrinc/tmaxapi.h>
int tmax_get_svclist(char *buf, int bufsize)
●パラメータ
説明
パラメータ
以下のサイズで割り当てたバッファーに、自身が属しているサーバーがもつサー
ビスの名前を取得します
buf
サービス数(tmax_get_svccnt()の戻り値) x XATMI_SERVICE_NAME_LENGTH
以下の値です
bufsize
サービス数(tmax_get_svccnt()の戻り値) x XATMI_SERVICE_NAME_LENGTH
●戻り値
説明
戻り値
関数が呼び出しに成功した場合です
0
関数が呼び出しに失敗した場合です。tperrnoにエラーコードが設定されます
-1
●エラー
tmax_get_svclist()が正常に実行されなかった場合、tperrnoに以下の値のいずれかが設定されます。
296   Tmax リファレンスガイド
説明
エラーコード
バッファーのサイズが（サービス数x XATMI_SERVICE_NAME_LENGTH）より小さ
い場合、あるいはNULLの場合に発生します
[TPEINVAL]
●例
<サーバー・プログラム>
#include <stdio.h>
#include <stdlib.h>
#include <usrinc/tmaxapi.h>
GETSVC(TPSVCINFO *msg)
{
int
i;
int len, ret, size;
char *buf;
char *ptr;
printf(“GETSVC service is started!\n”);
len = tmax_get_svccnt();
if (len < 0) {
printf(“tmax_get_svccnt fail[%d]\n”, tperrno);
tpreturn(TPFAIL, 0, 0, 0, 0);
}
printf(“SVCCNT = %d\n”, len);
size = len * XATMI_SERVICE_NAME_LENGTH;
buf = malloc(size);
if (buf == NULL) {
printf(“buf is NULL\n”);
tpreturn(TPFAIL, 0, 0, 0, 0);
}
ret = tmax_get_svclist(buf, size);
if (ret < 0) {
printf(“tmax_get_svclist fail[%d]\n”, tperrno);
tpreturn(TPFAIL, 0, 0, 0, 0);
}
for (i = 0; i < len; i++) {
ptr = buf;
printf(“%dth SVC[%s]\n”, i, ptr);
buf += XATMI_SERVICE_NAME_LENGTH;
}
free(buf);
tpreturn(TPSUCCESS,0,(char *)msg->data, 0,0);
}

