param = get_threadspecificdata();
param->state = EXIT;
pthread_cond_signal(&param->cond);
pthread_join(param->tid, &ret);
pthread_mutex_destroy(&param->mutex);
pthread_cond_destroy(&param->cond);
printf("user_create_thread destroyed\n");
}
