#include <stdio.h>
#include <usrinc/atmi.h>
void main(int argc, char* argv[])
{
char *buf;
long len;
int ret;
ret=tpstart((TPSTART_T *)NULL);
if (ret==-1) { error processing }
buf=tpalloc(“STRING”, NULL, 0);
if (buf==NULL) { error processing }
data process....
