if (test[I])==NULL} { error processing }
strcpy(test[i],argv[i+1]);
cd[i]=tpacall(“SERVICE”, test[i], 0, TPNOTIME);
)
ret=tpcancel(cd[1]);         /* 2番目の応答をキャンセルします */
if (ret==-1) { error processing }
