.....
ctxp = (CTX_T *)tpsavectx();
.....
ret=tpcancelctx(ctxp);
if (ret<0) {
error process routine
}
.....
tpreturn(TPFAIL, sqlca.sqlcode, NULL, 0, TPNOFLAGS);
}

